/**
 * The gb18030 index: a list of 23,940 code points, one per pointer, encoded as a base64 string of
 * Uint16LE values and decoded into a {@link Uint16Array} once at module load (replaces a ~178KB
 * array literal with a ~64KB string).
 */
const GB18030_INDEX_BASE64 =
  "";

const BASE64_CHARS = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";

/**
 * Decode a base64 string into its raw bytes.
 *
 * @param input The base64-encoded string to decode.
 * @returns The decoded bytes.
 */
const decodeBase64 = (input: string): Uint8Array => {
  const output = new Uint8Array((input.length * 3) >> 2);
  let buffer = 0;
  let bits = 0;
  let index = 0;

  for (const char of input) {
    if (char === "=") break;
    buffer = (buffer << 6) | BASE64_CHARS.indexOf(char);
    bits += 6;

    if (bits >= 8) {
      bits -= 8;
      output[index] = (buffer >> bits) & 0xff;
      index += 1;
    }
  }

  return output;
};

/**
 * Decode base64-encoded Uint16LE data into a {@link Uint16Array}.
 *
 * @param base64 The base64-encoded Uint16LE string to decode.
 * @returns The decoded Uint16 array.
 */
const decodeIndex = (base64: string): Uint16Array => {
  const bytes = decodeBase64(base64);
  const result = new Uint16Array(bytes.length >> 1);
  const view = new DataView(bytes.buffer, bytes.byteOffset, bytes.byteLength);

  for (let i = 0; i < result.length; i += 1) result[i] = view.getUint16(i * 2, true);

  return result;
};

